    where m.board_id = p_board_id
      and m.user_id = auth.uid()
      and m.role = p_role
  );
$$;

create function public.board_not_archived(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived = false
  );
$$;

create function public.enforce_card_editor_target(p_card_id bigint, p_board_id bigint, p_role text)
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if public.is_board_member(p_board_id, 'editor') is false then
    raise exception 'card can only be moved to a board where the user is an editor';
  end if;

  return new;
end;
$$;

create trigger cards_enforce_editor_target
before update of board_id on public.cards
for each row execute function public.enforce_card_editor_target(old.id, new.board_id, auth.role());

