on public.board_members
for select
to authenticated
using (public.is_board_member(board_id, any(array['viewer', 'editor'])));

create policy cards_select_members
on public.cards
for select
to authenticated
using (public.is_board_member(board_id, 'viewer') or public.is_board_member(board_id, 'editor'));

create policy cards_insert_editors
on public.cards
for insert
to authenticated
with check (
  public.is_board_member(board_id, 'editor')
  and public.board_not_archived(board_id)
);

create policy cards_update_editors
on public.cards
for update
to authenticated
using (
  public.is_board_member(board_id, 'editor')
  and public.board_not_archived(board_id)
)
with check (
  public.is_board_member(board_id, 'editor')
  and public.board_not_archived(board_id)
);

create policy cards_delete_editors
on public.cards
for delete
to authenticated
