create function public.is_friend_of(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.friendships f
    where (f.requester_id = p_user_id and f.addressee_id = auth.uid())
       or (f.requester_id = auth.uid() and f.addressee_id = p_user_id)
       and f.status = 'accepted'
  );
