create function public.post_author_unchanged(p_old_id bigint, p_new_author_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.posts p
    where p.id = p_old_id
      and p.author_id = p_new_author_id
  );
$$;

create function public.friendship_status_unchanged(p_old_requester_id uuid, p_old_addressee_id uuid, p_new_status text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.friendships f
    where f.requester_id = p_old_requester_id
      and f.addressee_id = p_old_addressee_id
      and f.status = p_new_status
  );
$$;

create function public.check_friendship_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
    raise exception 'friendship participants cannot be changed';
  end if;

  if old.status = 'accepted' then
    raise exception 'only pending requests can be updated';
  end if;

  if new.status <> 'accepted' then
    raise exception 'only pending requests can be accepted';
  end if;

  if new.requester_id = auth.uid() then
    raise exception 'requester cannot accept their own request';
  end if;

  if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
    raise exception 'only the addressee of a pending request can accept it';
  end if;

  return new;
end;
$$;

create trigger friendships_check_update
before update on public.friendships
for each row execute function public.check_friendship_update();

create policy posts_select
on public.posts
for select
to anon, authenticated
using (
  audience = 'public'
  or author_id = auth.uid()
  or public.is_friend_of(auth.uid())
);

