on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy posts_update
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid() and not public.post_author_unchanged(id, author_id));

create policy posts_delete
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy friendships_select
on public.friendships
for select
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid());

create policy friendships_insert
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

create policy friendships_update
on public.friendships
for update
to authenticated
using (requester_id = auth.uid() or addressee_id = auth.uid())
with check (requester_id = auth.uid() or addressee_id = auth.uid());

revoke all on public.friendships, public.posts from anon;
revoke all on public.friendships, public.posts from authenticated;

grant select on public.posts to anon;
grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;

grant all on public.friendships, public.posts to service_role;

