create function public.is_resident_of(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.residents r
    where r.unit_id = p_unit_id
      and r.user_id = auth.uid()
  );
$$;

create function public.is_staff_of_building(p_building_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.building_staff s
    where s.building_id = p_building_id
      and s.user_id = auth.uid()
  );
$$;

create function public.get_building_id_of_unit(p_unit_id bigint)
returns bigint
language sql
stable
security definer
set search_path = public
as $$
  select u.building_id
  from public.units u
  where u.id = p_unit_id;
$$;

create policy units_select
on public.units
for select
to authenticated
using (
  public.is_resident_of(id)
  or public.is_staff_of_building(building_id)
);

create policy requests_select
on public.requests
for select
to authenticated
using (
  public.is_resident_of(unit_id)
  or public.is_staff_of_building(public.get_building_id_of_unit(unit_id))
);

create policy requests_insert
on public.requests
for insert
to authenticated
with check (
  created_by = auth.uid()
  and status = 'open'
  and public.is_resident_of(unit_id)
);

create policy requests_update
on public.requests
for update
to authenticated
using (
  public.is_staff_of_building(public.get_building_id_of_unit(unit_id))
)
with check (
  public.is_staff_of_building(public.get_building_id_of_unit(unit_id))
);

create policy request_photos_select
on public.request_photos
for select
to authenticated
using (
  exists (
    select 1
    from public.requests r
    where r.id = request_photos.request_id
      and (
        public.is_resident_of(r.unit_id)
        or public.is_staff_of_building(public.get_building_id_of_unit(r.unit_id))
      )
  )
);

create policy request_photos_insert
on public.request_photos
for insert
to authenticated
with check (
  exists (
    select 1
    from public.requests r
    where r.id = request_photos.request_id
      and (
        public.is_resident_of(r.unit_id)
        or public.is_staff_of_building(public.get_building_id_of_unit(r.unit_id))
      )
  )
);

revoke all on public.units, public.residents, public.building_staff, public.requests, public.request_photos from anon;
revoke all on public.units, public.residents, public.building_staff, public.requests, public.request_photos from authenticated;

grant select on public.units, public.requests, public.request_photos to authenticated;
grant insert, update on public.requests to authenticated;
grant insert on public.request_photos to authenticated;

revoke all on public.residents, public.building_staff from authenticated;

grant all on public.units, public.residents, public.building_staff, public.requests, public.request_photos to service_role;
