alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy auctions_select on public.auctions
  for select to authenticated
  using (true);

create policy bids_select on public.bids
  for select to authenticated
  using (bidder_id = auth.uid() or exists (select 1 from public.auctions a where a.id = auction_id and a.seller_id = auth.uid()));

create function public.place_bid(p_auction_id bigint, p_amount numeric) returns numeric
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current numeric;
begin
  if v_uid is null then
    raise exception 'not signed in';
  end if;
  select * into v_auction from public.auctions where id = p_auction_id for update;
  if not found or v_auction.ends_at <= now() then
    raise exception 'auction not found or ended';
  end if;
  if v_auction.seller_id = v_uid then
    raise exception 'cannot bid on own auction';
  end if;
  select highest_bid into v_current from public.auctions where id = p_auction_id;
  if v_current is null then
    if p_amount <= v_auction.starting_price then
      raise exception 'bid too low';
    end if;
  else
    if p_amount <= v_current + v_auction.min_increment then
      raise exception 'bid too low';
    end if;
  end if;
  insert into public.bids (auction_id, bidder_id, amount) values (p_auction_id, v_uid, p_amount);
  update public.auctions set highest_bid = p_amount, highest_bidder = v_uid where id = p_auction_id;
  return p_amount;
end
$$;
```

```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy "Authenticated users can view all auctions"
on public.auctions
for select
to authenticated
using (true);

create policy "Bidders and sellers can view bids"
on public.bids
for select
to authenticated
using (
  exists (
    select 1
    from public.auctions a
    where a.id = bids.auction_id
      and (bids.bidder_id = auth.uid() or a.seller_id = auth.uid())
  )
);

create or replace function public.place_bid(
  p_auction_id bigint,
  p_amount numeric
)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest numeric;
  v_increment numeric;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'cannot bid on own auction';
  end if;

  select highest_bid, min_increment into v_current_highest, v_increment
  from public.auctions
  where id = p_auction_id;

  if p_amount <= v_current_highest + v_increment then
    raise exception 'bid too low';
  end if;

  if v_current_highest is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid below starting price';
    end if;
  else
    if p_amount <= v_current_highest + v_increment then
      raise exception 'bid too low';
    end if;
  end if;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, p_amount, now());

  return p_amount;
end
$$;

revoke all on public.auctions, public.bids from anon;
revoke all on public.auctions, public.bids from authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;

grant execute on function public.place_bid(bigint, numeric) to authenticated;

grant all on public.auctions, public.bids to service_role;
grant execute on function public.place_bid(bigint, numeric) to service_role;
```

