  p_amount numeric
)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest numeric;
  v_increment numeric;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'cannot bid on own auction';
  end if;

  select highest_bid, min_increment into v_current_highest, v_increment
  from public.auctions
  where id = p_auction_id;

  if p_amount <= v_current_highest + v_increment then
    raise exception 'bid too low';
  end if;

  if v_current_highest is null then
    if p_amount < v_auction.starting_price then
      raise exception 'bid below starting price';
    end if;
  else
    if p_amount <= v_current_highest + v_increment then
      raise exception 'bid too low';
    end if;
  end if;

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, p_amount, now());

  return p_amount;
end
$$;

