$$;

create function public.class_spots_before_update()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.class_id <> old.class_id or new.user_id <> old.user_id then
    raise exception 'class_id and user_id cannot be changed';
  end if;

  if old.status = 'enrolled' then
    raise exception 'only waitlisted spots can be moved';
  end if;

  if new.status = 'enrolled' then
    if public.class_enrolled_count(new.class_id) >= public.class_capacity(new.class_id) then
      raise exception 'no room for enrolled status';
    end if;
  end if;

  return new;
end;
$$;

