$$;

create function public.is_instructor(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.classes where id = p_class_id and instructor_id = auth.uid());
$$;

create policy classes_select_authenticated
on public.classes
for select
to authenticated
using (true);

create policy class_spots_select_own_or_instructor
on public.class_spots
for select
to authenticated
using (user_id = auth.uid() or public.is_instructor(class_id));

create policy class_spots_insert_own_valid
on public.class_spots
for insert
to authenticated
with check (
  user_id = auth.uid()
  and status in ('enrolled', 'waitlisted')
  and (
    status = 'enrolled'
    and public.class_enrolled_count(class_id) < public.class_capacity(class_id)
  )
);

create policy class_spots_update_own_waitlisted_to_enrolled
on public.class_spots
for update
to authenticated
using (
  user_id = auth.uid()
  and status = 'waitlisted'
  and public.class_enrolled_count(class_id) < public.class_capacity(class_id)
)
with check (
  user_id = auth.uid()
  and status = 'enrolled'
);

create policy class_spots_delete_own
on public.class_spots
for delete
to authenticated
using (user_id = auth.uid());

create policy class_spots_delete_instructor
on public.class_spots
for delete
to authenticated
using (public.is_instructor(class_id));

revoke all on public.classes, public.class_spots from anon;
revoke all on public.class_enrolled_count, public.class_capacity, public.is_instructor from anon;

revoke all on public.classes, public.class_spots from authenticated;
revoke all on public.class_enrolled_count, public.class_capacity, public.is_instructor from authenticated;

grant select on public.classes to authenticated;
grant select, insert, update, delete on public.class_spots to authenticated;

grant execute on function public.class_enrolled_count(bigint) to authenticated;
grant execute on function public.class_capacity(bigint) to authenticated;
grant execute on function public.is_instructor(bigint) to authenticated;

grant all on public.classes, public.class_spots to service_role;
grant all on function public.class_enrolled_count(bigint), public.class_capacity(bigint), public.is_instructor(bigint) to service_role;
